<template><div class="page"><header class="page-header"><div><p class="eyebrow">{{ vehicleId?'Vehicle inventory':'Inventory' }}</p><h1 class="page-title">Parts</h1><p class="page-subtitle">{{ vehicleId?'Parts assigned to vehicle #'+vehicleId:'Browse all cataloged parts across your workspace.' }}</p></div><div class="header-actions"><button v-if="vehicleId" class="btn btn-ghost" @click="$router.push('/vehicles')"><AppIcon name="back"/>Vehicles</button><button class="btn btn-primary" @click="showModal=true"><AppIcon name="plus"/>Add part</button></div></header>
<section class="panel table-panel"><div class="toolbar"><span class="record-count">{{ parts.length }} {{ parts.length===1?'part':'parts' }}</span></div><div v-if="loading" class="loading-state"><span class="loader"></span></div><div v-else-if="parts.length" class="table-wrap"><table class="data-table"><thead><tr><th>Part</th><th>OEM number</th><th>Location</th><th>Est. value</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in parts" :key="p.id"><td><div class="primary-cell">{{ p.name }}</div><div class="secondary-cell">{{ p.condition_note||'No condition notes' }}</div></td><td>{{ p.oem_number }}</td><td>{{ [p.loc_locker,p.loc_bin].filter(Boolean).join(' · ')||'—' }}</td><td class="money">{{ money(p.est_value_c) }}</td><td><span class="status" :class="p.status==='SOLD'?'status-green':'status-amber'">{{ pretty(p.status) }}</span></td><td><button class="btn btn-ghost btn-sm" @click="$router.push({path:'/listing',query:{part_id:p.id}})">Create listing <AppIcon name="arrow"/></button></td></tr></tbody></table></div><div v-else class="empty-state"><span class="empty-icon"><AppIcon name="box"/></span><h3>No parts found</h3><p>Add a part to start building this inventory.</p></div></section>
<div v-if="showModal" class="modal-backdrop-custom" @click.self="closeModal"><form class="dialog" @submit.prevent="submitPart"><header class="dialog-header"><div><h2>Add a part</h2><p>Catalog a part and its storage location.</p></div><button type="button" class="icon-button" @click="closeModal"><AppIcon name="close"/></button></header><div class="dialog-body form-grid"><label class="field-full"><span class="form-label">Part name</span><input v-model="form.name" class="form-control" placeholder="Front left headlight assembly" required></label><label><span class="form-label">OEM number</span><input v-model="form.oem_number" class="form-control" required></label><label v-if="!vehicleId"><span class="form-label">Vehicle ID</span><input v-model.number="form.vehicle_id" type="number" min="1" class="form-control" required></label><label class="field-full"><span class="form-label">Condition notes</span><input v-model="form.condition_note" class="form-control" placeholder="Light wear, fully tested"></label><label><span class="form-label">Locker</span><input v-model="form.loc_locker" class="form-control" placeholder="A3"></label><label><span class="form-label">Bin</span><input v-model="form.loc_bin" class="form-control" placeholder="12"></label><label><span class="form-label">Est. value ($)</span><input v-model.number="form.est_value_c" type="number" min="0" step=".01" class="form-control" required></label><label><span class="form-label">Status</span><select v-model="form.status" class="form-select"><option>IN_BIN</option><option>LISTED</option><option>SOLD</option></select></label></div><footer class="dialog-footer"><button type="button" class="btn btn-ghost" @click="closeModal">Cancel</button><button class="btn btn-primary">Save part</button></footer></form></div></div></template>
<script setup>import{ref,onMounted,computed}from'vue';import superagent from'superagent';import{apiUrl}from'../api';import{useRoute}from'vue-router';import AppIcon from'../components/AppIcon.vue';const route=useRoute(),vehicleId=computed(()=>route.query.vehicle_id?Number(route.query.vehicle_id):null),parts=ref([]),loading=ref(true),showModal=ref(false);const blank=()=>({vehicle_id:vehicleId.value||'',name:'',oem_number:'',condition_note:'',loc_locker:'',loc_bin:'',est_value_c:'',status:'IN_BIN'}),form=ref(blank());const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v||0),pretty=v=>(v||'').replaceAll('_',' ').toLowerCase().replace(/^./,x=>x.toUpperCase());function closeModal(){showModal.value=false;form.value=blank()}async function fetchParts(){loading.value=true;try{const url=apiUrl('/parts/v1')+(vehicleId.value?'?vehicle_id='+vehicleId.value:'');const r=await superagent.get(url);parts.value=Array.isArray(r.body)?r.body:[]}catch{parts.value=[]}finally{loading.value=false}}async function submitPart(){try{await superagent.post(apiUrl('/parts/v1')).send({...form.value,vehicle_id:vehicleId.value||Number(form.value.vehicle_id)});await fetchParts();closeModal()}catch{alert('Unable to add this part. Please check the details and try again.')}}onMounted(fetchParts)</script><style scoped>.header-actions{display:flex;gap:10px}@media(max-width:700px){.header-actions{display:grid;grid-template-columns:1fr 1fr}}</style>
